window.switchTab = function (tab) {const bookTab = document.getElementById("tab-book");const quoteTab = document.getElementById("tab-quote");const tabBtns = document.querySelectorAll(".ftab");if (!bookTab || !quoteTab) return;if (tab === "book") {bookTab.style.display = "block";quoteTab.style.display = "none";if (tabBtns[0]) tabBtns[0].classList.add("active");if (tabBtns[1]) tabBtns[1].classList.remove("active");} else {bookTab.style.display = "none";quoteTab.style.display = "block";if (tabBtns[0]) tabBtns[0].classList.remove("active");if (tabBtns[1]) tabBtns[1].classList.add("active");}};window.requestQuote = function () {window.switchTab("quote");const bookingSec = document.getElementById("booking");if (bookingSec) bookingSec.scrollIntoView({ behavior: "smooth" });};window.chooseTrailer = function (size) {window.switchTab("book");const select = document.getElementById("trailer");if (select) {select.value = size;window.calculatePrice();}const bookingSec = document.getElementById("booking");if (bookingSec) bookingSec.scrollIntoView({ behavior: "smooth" });};window.calculatePrice = function () {const trailer = document.getElementById("trailer")?.value;const startDate = document.getElementById("startDate")?.value;const endDate = document.getElementById("endDate")?.value;const estimateBox = document.getElementById("estimateBox");const estimateNote = document.getElementById("estimateNote");const estimateEl = document.getElementById("estimate");const breakEl = document.getElementById("estimateBreak");const hiddenEstimate = document.getElementById("hiddenEstimate");if (!trailer || !startDate || !endDate) {if (estimateBox) estimateBox.style.display = "none";if (estimateNote) estimateNote.style.display = "none";return;}let dailyRate = 0;if (trailer.includes("Mini")) dailyRate = 140;else if (trailer.includes("Standard")) dailyRate = 220;else if (trailer.includes("Maxi")) dailyRate = 310;const start = new Date(startDate);const end = new Date(endDate);const diffTime = Math.abs(end - start);const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24)) + 1;if (isNaN(diffDays) || diffDays <= 0) {if (estimateBox) estimateBox.style.display = "none";return;}const total = dailyRate * diffDays;if (estimateEl) estimateEl.textContent = `£${total}`;if (breakEl) breakEl.textContent = `${diffDays} day(s) @ £${dailyRate}/day`;if (hiddenEstimate) hiddenEstimate.value = `£${total}`;if (estimateBox) estimateBox.style.display = "flex";if (estimateNote) estimateNote.style.display = "block";};window.handleBooking = async function (event) {event.preventDefault();const form = document.getElementById("bookingForm");const btn = document.getElementById("bookBtn");const successBox = document.getElementById("success");if (btn) btn.disabled = true;const formData = new FormData(form);const payload = Object.fromEntries(formData.entries());try {await fetch("/api/bookings", {method: "POST",headers: { "Content-Type": "application/json" },body: JSON.stringify(payload)});fetch(form.action, {method: "POST",body: formData,headers: { Accept: "application/json" }});if (form) form.style.display = "none";if (successBox) successBox.style.display = "block";} catch (err) {console.error("Booking error:", err);alert("There was an error saving your booking request. Please try again.");} finally {if (btn) btn.disabled = false;}};window.handleQuote = async function (event) {event.preventDefault();const form = document.getElementById("quoteForm");const btn = document.getElementById("quoteBtn");const successBox = document.getElementById("quoteSuccess");if (btn) btn.disabled = true;const formData = new FormData(form);const payload = Object.fromEntries(formData.entries());try {await fetch("/api/quotes", {method: "POST",headers: { "Content-Type": "application/json" },body: JSON.stringify(payload)});fetch(form.action, {method: "POST",body: formData,headers: { Accept: "application/json" }});if (form) form.style.display = "none";if (successBox) successBox.style.display = "block";} catch (err) {console.error("Quote error:", err);alert("There was an error submitting your quote. Please try again.");} finally {if (btn) btn.disabled = false;}};document.addEventListener("DOMContentLoaded", () => {const loginForm = document.getElementById("login-form");const passwordInput = document.getElementById("password-input");const loginError = document.getElementById("login-error");const adminDashboard = document.getElementById("admin-dashboard");const loginContainer = document.getElementById("login-container");const logoutBtn = document.getElementById("logout-btn");if (adminDashboard && loginContainer) {checkSessionState();}if (loginForm) {loginForm.addEventListener("submit", async function (e) {e.preventDefault();const enteredPassword = passwordInput ? passwordInput.value.trim() : "";if (!enteredPassword) {showError("Please enter a password.");return;}setLoadingState(true);try {const response = await fetch("/api/login", {method: "POST",headers: { "Content-Type": "application/json" },body: JSON.stringify({ password: enteredPassword }),});const result = await response.json();if (response.ok && result.success) {sessionStorage.setItem("skipit_admin_auth", "true");showDashboard();} else {showError(result.message || "Incorrect password. Access denied.");if (passwordInput) passwordInput.value = "";}} catch (err) {showError("Server error. Please check your connection and try again.");} finally {setLoadingState(false);}});}if (logoutBtn) {logoutBtn.addEventListener("click", () => {sessionStorage.removeItem("skipit_admin_auth");showLogin();});}function checkSessionState() {const isAuthenticated = sessionStorage.getItem("skipit_admin_auth") === "true";if (isAuthenticated) showDashboard();else showLogin();}function showDashboard() {if (loginContainer) loginContainer.style.display = "none";if (adminDashboard) adminDashboard.style.display = "block";if (loginError) loginError.textContent = "";loadDashboardData();}function showLogin() {if (loginContainer) loginContainer.style.display = "block";if (adminDashboard) adminDashboard.style.display = "none";}function showError(msg) {if (loginError) {loginError.textContent = msg;loginError.style.color = "#d9534f";}}function setLoadingState(isLoading) {const submitBtn = loginForm ? loginForm.querySelector('button[type="submit"]') : null;if (submitBtn) {submitBtn.disabled = isLoading;submitBtn.textContent = isLoading ? "Verifying..." : "Log In";}}async function loadDashboardData() {try {const response = await fetch("/api/admin-data");const data = await response.json();const bookings = data.bookings || [];const quotes = data.quotes || [];const bookingCountEl = document.getElementById("booking-count");const quoteCountEl = document.getElementById("quote-count");const pendingCountEl = document.getElementById("pending-count");if (bookingCountEl) bookingCountEl.textContent = bookings.length;if (quoteCountEl) quoteCountEl.textContent = quotes.length;if (pendingCountEl) pendingCountEl.textContent = bookings.length + quotes.length;renderBookingsTable(bookings);renderQuotesTable(quotes);} catch (err) {console.error("Error loading admin data:", err);}}function renderBookingsTable(bookings) {const tableContainer = document.getElementById("bookings-table");if (!tableContainer) return;if (bookings.length === 0) {tableContainer.innerHTML = "<p>No bookings found in database.</p>";return;}let html = `<table><thead><tr><th>ID</th><th>Name</th><th>Email</th><th>Date</th><th>Submitted</th></tr></thead><tbody>`;bookings.forEach((b) => {html += `<tr><td><code>#${b.id}</code></td><td>${escapeHtml(b.customer_name || 'N/A')}</td><td>${escapeHtml(b.email || 'N/A')}</td><td>${escapeHtml(b.booking_date || 'N/A')}</td><td>${b.created_at ? new Date(b.created_at).toLocaleString() : 'N/A'}</td></tr>`;});html += "</tbody></table>";tableContainer.innerHTML = html;}function renderQuotesTable(quotes) {const tableContainer = document.getElementById("quotes-table");if (!tableContainer) return;if (quotes.length === 0) {tableContainer.innerHTML = "<p>No quote requests found in database.</p>";return;}let html = `<table><thead><tr><th>ID</th><th>Name</th><th>Details</th><th>Submitted</th></tr></thead><tbody>`;quotes.forEach((q) => {html += `<tr><td><code>#${q.id}</code></td><td>${escapeHtml(q.customer_name || 'N/A')}</td><td>${escapeHtml(q.details || 'N/A')}</td><td>${q.created_at ? new Date(q.created_at).toLocaleString() : 'N/A'}</td></tr>`;});html += "</tbody></table>";tableContainer.innerHTML = html;}function escapeHtml(str) {return String(str).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");}});